n=20
g=[[0]*n for _ in range(n)]
markers=[(2,6),(3,19),(4,5),(7,1),(8,19),(12,9),(17,13),(19,15)]
for r,c in markers:g[r][c]=1
for r in range(2,9):
 for c in range(9,16):g[r][c]=2
# top
for r in range(0,2):
 for c in range(9,16):g[r][c]=2
# left/right extensions by blocked marker on each side, extending from square to boundary
for r in range(2,9):
 if not any(rr==r and cc<9 for rr,cc in markers):
  for c in range(9):g[r][c]=2
 if not any(rr==r and cc>=16 for rr,cc in markers):
  for c in range(16,20):g[r][c]=2
# bottom
for c in range(9,16):
 if not any(cc==c and rr>8 for rr,cc in markers):
  for r in range(9,20):g[r][c]=2
print('\n'.join(' '.join(map(str,row)) for row in g))
